    ctx.strokeStyle = '#43342E'; ctx.lineWidth = 11; ctx.strokeText('PATISSERIE · 바게트 하우스', w * 0.5, 92);
    ctx.fillStyle = '#DC2626'; ctx.fillText('PATISSERIE · 바게트 하우스', w * 0.5, 92);
