    ctx.strokeStyle = '#43342E'; ctx.lineWidth = 11; ctx.strokeText('FLORES & CO. · 플라워샵', w * 0.5, 92);
    ctx.fillStyle = '#BE185D'; ctx.fillText('FLORES & CO. · 플라워샵', w * 0.5, 92);
