      const tray = createRoundedToyMesh(0.74, 0.06, 0.52, MAT.woodWarm, 0, 0.03, 0, 0.03);
      const parchment = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.015, 0.44), MAT.cream);
      parchment.position.y = 0.065;
