function renderShopUpgradeCatalog() {
  if (!focusedShopId || !dom.fcatItemsGrid) return;
  const tpl = STANDALONE_SHOPS_TEMPLATE.find((s) => s.shopId === focusedShopId);
  const st = state.standaloneShops?.[focusedShopId];
  if (!tpl || !st) return;

  const { visitRev, cycleRev } = calcStandaloneShopStats(focusedShopId);

  const headerIco = document.getElementById('fcat-header-ico');
  if (headerIco) headerIco.innerHTML = createCustomSVGIcon(tpl.svgIcon, 20);
  if (dom.fcatSheetTitle) dom.fcatSheetTitle.textContent = '부티크 상가 3D 설비 상점';
  if (dom.fcatRoomBadge) dom.fcatRoomBadge.textContent = tpl.name;
  if (dom.fcatBonusBadge) dom.fcatBonusBadge.textContent = `방문 +${visitRev}만 · 주기 +${cycleRev}만`;

  dom.fcatTabsRow?.classList.add('hidden');
  dom.fcatItemsGrid.classList.remove('cols-5');
  dom.fcatItemsGrid.classList.add('cols-3');

  const upgCatalog = getShopUpgradeCatalogFor(tpl);
  dom.fcatItemsGrid.innerHTML = upgCatalog.map((upg) => {
    const installed = !!st.upgrades?.[upg.id];
    let btnHtml = '';
    if (!st.owned) {
      btnHtml = `
        <button type="button" data-shop-acquire-first="1" class="jelly-action-btn btn-coral-lip w-full py-1.5 !text-[12px]">
          ${createCustomSVGIcon('crown_badge', 15)}
          <span>상가 인수 (${tpl.buyCost}만)</span>
        </button>`;
    } else if (installed) {
      btnHtml = `
        <button type="button" disabled class="kw-chip tone-mint w-full justify-center py-1.5">
          ${createCustomSVGIcon('sparkle_star', 14)}
          <span>3D 시공 완료</span>
        </button>`;
    } else {
      btnHtml = `
        <button type="button" data-shop-upg="${upg.id}" class="jelly-action-btn btn-gold-lip w-full py-1.5 !text-[12px]">
          ${createCustomSVGIcon('coin_stack', 15)}
          <span>${upg.cost}만 증설</span>
        </button>`;
    }

    return `
      <div class="fcat-item-card ${installed ? 'equipped' : ''}">
        <div class="fcat-thumb-stage">${getOrRender3DCatalogPreview(upg.id, 188, 92)}</div>
        <div class="space-y-1">
          <div class="font-title text-[13px] text-[#3A2E2B] leading-snug">${upg.name}</div>
          <span class="kw-chip tone-${upg.tone} !text-[10.5px] !py-0.5 !px-2">${upg.chip}</span>
        </div>
        ${btnHtml}
      </div>
    `;
  }).join('');

  dom.fcatItemsGrid.querySelectorAll('[data-shop-acquire-first]').forEach((btn) => {
    btn.addEventListener('click', () => acquireStandaloneShopAction(focusedShopId));
  });
  dom.fcatItemsGrid.querySelectorAll('[data-shop-upg]').forEach((btn) => {
    btn.addEventListener('click', () => buyShopUpgradeAction(focusedShopId, btn.getAttribute('data-shop-upg')));
  });
}

function acquireStandaloneShopAction(shopId) {
  const tpl = STANDALONE_SHOPS_TEMPLATE.find((s) => s.shopId === shopId);
  const st = state.standaloneShops?.[shopId];
  if (!tpl || !st || st.owned) return;
  if (!spendGold(tpl.buyCost)) return;

  st.owned = true;
  rebuildStandaloneShop3D(shopId);
  spawnPoofParticles3D(tpl.x, 2.4, tpl.z, 0xFFD93D, 16);
  spawnShockwaveRing3D(tpl.x, 0.35, tpl.z, 0xFF6B6B, 5.5);
  spawnJackpotText3D(tpl.x, 3.6, tpl.z, `${tpl.name} 직영 인수!`, 'crown_badge');

  updateTopHUDTargets();
  renderShopSwitcherChips();
  renderFocusedShopPanel();
  renderShopUpgradeCatalog();
  showToast(`[${tpl.name}] 직영 인수 완료! 손님 결제금이 자산에 합산됩니다!`, 'gold');
  saveGameState();
}

function buyShopUpgradeAction(shopId, upgId) {
  const tpl = STANDALONE_SHOPS_TEMPLATE.find((s) => s.shopId === shopId);
  const st = state.standaloneShops?.[shopId];
  const upg = getShopUpgradeCatalogFor(tpl).find((u) => u.id === upgId);
  if (!tpl || !st || !upg || !st.owned || st.upgrades[upgId]) return;
  if (!spendGold(upg.cost)) return;

  st.upgrades[upgId] = true;
  syncHarborBridgeGate3D();
  state.townHappinessBoost = Math.min(65, (state.townHappinessBoost || 0) + 6);
  tuckFocusDockTemporarily(1.25);
  rebuildStandaloneShop3D(shopId);
  const sGrp = standaloneShop3D[shopId]?.group;
  if (sGrp) {
    playDropBouncePlacement3D(sGrp, tpl.x, 0.35, tpl.z);
  }
  showSpeechBubble3D(`staff_${shopId}`, tpl.x, 2.6, tpl.z, upg.reaction, 3.6, true);

  updateTopHUDTargets();
  renderFocusedShopPanel();
  renderShopUpgradeCatalog();
  showToast(`[${tpl.name}] ${upg.name} 3D 시공 & 착지 완료!`, 'mint');
  saveGameState();
}

// =========================================================
// 15. 택타일 코지 팝 타운 경영 수첩(4탭 풀 구성) · 입주 모집 · 부지 착공 모달
// =========================================================
function refreshQuestRedDot() {
  let claimable = 0;
  let doneTotal = 0;
  for (const q of QUEST_LIST) {
    const isClaimed = state.claimedQuests.includes(q.id);
    if (isClaimed) doneTotal += 1;
    else if (q.check(state)) claimable += 1;
  }
  if (dom.fabRedDot) {
    dom.fabRedDot.textContent = String(claimable);
    dom.fabRedDot.classList.toggle('hidden', claimable === 0);
  }
  if (dom.tabDotQuests) {
    dom.tabDotQuests.classList.toggle('hidden', claimable === 0);
  }
  if (dom.modalQuestSummary) {
    dom.modalQuestSummary.textContent = `${doneTotal}/${QUEST_LIST.length}`;
  }
}

function openNotebookModal(tab = null) {
  closeAllModalsImmediate('notebook-modal');
  if (tab) activeNotebookTab = tab;
  document.querySelectorAll('[data-ntab]').forEach((b) => {
    b.classList.toggle('active', b.getAttribute('data-ntab') === activeNotebookTab);
  });
  renderNotebookUnifiedBody();
  dom.notebookModal?.classList.remove('hidden');
}

function renderNotebookUnifiedBody() {
  if (!dom.notebookBody) return;

  if (activeNotebookTab === 'quests') {
    const activeEp = getActiveEpisodeChapter();
    const epUrls = POPMART_ASSETS?.episodeIconUrls || [];
    const epHeaderHtml = activeEp ? `
      <div class="diary-card !bg-gradient-to-br !from-[#FFFBEB] !to-[#FEF3C7] !border-2 !border-[#F59E0B] space-y-2">
        <div class="flex items-center gap-2.5">
          <div class="w-12 h-12 rounded-2xl bg-[#FFFDF8] border-2 border-[#F59E0B] flex items-center justify-center shrink-0 overflow-hidden">
            ${epUrls[activeEp.iconIdx || 0]
              ? `<img src="${epUrls[activeEp.iconIdx || 0]}" alt="" class="toy-ico-img w-10 h-10" />`
              : createCustomSVGIcon('quest_trophy', 28)}
          </div>
          <div class="min-w-0 flex-1">
            <div class="flex items-center gap-1.5 flex-wrap">
              <span class="kw-chip tone-coral !text-[10px] !py-0.5 !px-2">${activeEp.code} · ${activeEp.rankRange}</span>
              <span class="kw-chip tone-gold !text-[10px] !py-0.5 !px-2">장기 스토리 에피소드</span>
            </div>
            <div class="font-title text-[14.5px] text-[#3A2E2B] mt-0.5">〈${activeEp.title}〉</div>
          </div>
        </div>
        <div class="rounded-xl bg-[#FFFDF9] border border-[#FDE68A] px-2.5 py-2 font-body text-[11.5px] font-bold text-[#69544C] leading-snug">
          ${activeEp.storyQuote}
        </div>
      </div>
    ` : '';

    const questCardsHtml = QUEST_LIST.map((q) => {
      const claimed = state.claimedQuests.includes(q.id);
      const ready = !claimed && q.check(state);
      const prog = q.progress ? q.progress(state) : { cur: ready || claimed ? 1 : 0, max: 1 };
      const pct = Math.min(100, Math.round((prog.cur / Math.max(1, prog.max)) * 100));
      const chBadge = q.chapter ? `<span class="px-1.5 py-0.5 rounded-full text-[9.5px] font-extrabold bg-[#FEF3C7] text-[#92400E] border border-[#F59E0B]">Ch.${q.chapter}</span>` : '';
      const epThumb = (q.chapter && epUrls[q.chapter - 1])
        ? `<img src="${epUrls[q.chapter - 1]}" alt="" class="toy-ico-img w-9 h-9" />`
        : createCustomSVGIcon(q.icon || 'quest_trophy', 28);

      return `
        <div class="diary-card flex items-center justify-between gap-2.5 ${ready ? '!bg-[#FFFDF2] !border-[#38E54D] !border-2' : ''}">
          <div class="flex items-center gap-2.5 min-w-0 flex-1">
            <div class="w-11 h-11 rounded-2xl bg-[#FFFDF7] border-2 border-[#E8CCB0] flex items-center justify-center shrink-0 overflow-hidden">
              ${epThumb}
            </div>
            <div class="min-w-0 flex-1 space-y-1">
              <div class="flex items-center gap-1.5 flex-wrap">
                ${chBadge}
                <span class="font-title text-[13.5px] text-[#3A2E2B]">${q.title}</span>
              </div>
              <div class="font-body text-[11px] font-semibold text-[#69544C] leading-snug">${q.desc || ''}</div>
              <div class="flex items-center gap-1.5 flex-wrap pt-0.5">
                <div class="candy-gauge-track max-w-[96px]">
                  <div class="candy-gauge-fill candy-mint" style="width:${claimed ? 100 : pct}%"></div>
                </div>
                <span class="kw-chip tone-gold !py-0.5 !px-1.5 !text-[10px]">+${q.reward}만</span>
                ${q.fameReward ? `<span class="kw-chip tone-sky !py-0.5 !px-1.5 !text-[10px]">✨ 명성 +${q.fameReward}</span>` : ''}
              </div>
            </div>
          </div>
          <div class="shrink-0">
            ${claimed
              ? createNotebookArtworkSVG('stamp_complete', 44)
              : ready
                ? `<button type="button" data-claim-q="${q.id}" class="jelly-action-btn btn-gold-lip px-3 py-2 !text-[11.5px]">보상 수령</button>`
                : `<button type="button" data-goto-q="${q.id}" class="tactile-pill-btn tone-cream !px-2.5 !py-1.5 !text-[11px]">바로가기</button>`}
          </div>
        </div>
      `;
    }).join('');

    dom.notebookBody.innerHTML = epHeaderHtml + questCardsHtml;

    dom.notebookBody.querySelectorAll('[data-claim-q]').forEach((btn) => {
      btn.addEventListener('click', (ev) => {
        const qid = btn.getAttribute('data-claim-q');
        const q = QUEST_LIST.find((x) => x.id === qid);
        if (!q || state.claimedQuests.includes(qid) || !q.check(state)) return;
        state.claimedQuests.push(qid);
        if (q.fameReward) {
          state.fame = (state.fame || 10) + q.fameReward;
        }
        addGold(q.reward, ev.clientX, ev.clientY);
        syncManagerAndEpisodeHUD();
        updateForbesRankAndHUD(true);
        renderNotebookUnifiedBody();
        showToast(`🎉 에피소드 보상 +${q.reward}만${q.fameReward ? ` & ✨ 명성 +${q.fameReward}pt` : ''} 수령!`, 'gold');
        saveGameState();
      });
    });

    dom.notebookBody.querySelectorAll('[data-goto-q]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const q = QUEST_LIST.find((x) => x.id === btn.getAttribute('data-goto-q'));
        if (!q) return;
        dom.notebookModal?.classList.add('hidden');
        if (q.openDuel) enterShowroomFlexDuel('ranked');
        else if (q.openForbes) openForbesModal();
        else if (q.openGarage) openGarageModal();
        else if (q.focusShop) focusCameraOnShop(q.focusShop);
        else if (q.focusLot && q.focusSubRoom) focusCameraOnRoom(`${q.focusLot}_${q.focusSubRoom}`);
        else if (q.openTab) openNotebookModal(q.openTab);
      });
    });
  } else if (activeNotebookTab === 'tenants') {
    const activeLotId = (state.activeTownStage === 2 && state.harborUnlocked) ? 'lot_harbor_main' : 'lot_main';
    const b = state.buildings[activeLotId] || state.buildings.lot_main;
    const roomsHtml = b.rooms.map((rm) => {
      const meta = ROOM_TYPE_META[rm.layoutType] || ROOM_TYPE_META.studio;
      const hDef = rm.household ? HOUSEHOLD_TYPES[rm.household.type] : null;
      const det = calcRoomRentDetail(b, rm);
      return `
        <div class="diary-card flex items-center justify-between gap-3">
          <div class="flex items-center gap-3 min-w-0 flex-1">
            ${rm.household
              ? createHouseholdAvatarSVG(rm.household.type, 48)
              : `<div class="w-12 h-12 rounded-2xl bg-[#FFFDF7] border-2 border-[#E8CCB0] flex items-center justify-center shrink-0">${createCustomSVGIcon(rm.unlocked ? meta.svgIcon : 'padlock_gold', 26)}</div>`}
            <div class="min-w-0 flex-1">
              <div class="flex items-center gap-1.5 flex-wrap">
                <span class="hotel-num-tag">${rm.name}호</span>
                <span class="kw-chip tone-${meta.tone}">${createCustomSVGIcon(meta.svgIcon, 13)}<span>${meta.badge}</span></span>
                ${hDef ? `<span class="role-accent-badge" style="background:${hDef.accentHex};">${hDef.label}</span>` : ''}
                ${det.isCapped ? `<span class="kw-chip tone-coral !text-[9.5px]">🔒 한도 ${det.rentCap}만</span>` : ''}
              </div>
              <div class="font-body text-[12px] font-semibold text-[#69544C] mt-1 break-keep leading-snug">
                ${!rm.unlocked
                  ? `미개방 호실 · <span class="whitespace-nowrap">개방 비용 ${rm.unlockCost}만</span>`
                  : rm.household
                    ? `${rm.household.familyName} · <span class="whitespace-nowrap">주기 월세 ${det.effectiveRent}만${det.isCapped ? `(잠재 ${det.uncappedRent}만)` : ''}</span> · <span class="whitespace-nowrap">행복도 ${Math.round(rm.household.happiness || 92)}%</span>`
                    : `공실 대기 중 · <span class="whitespace-nowrap">예상 월세 ${det.effectiveRent}만</span>`}
              </div>
            </div>
          </div>
          <button type="button" data-nb-room="${rm.id}" class="jelly-action-btn btn-mint-lip px-3.5 py-2 shrink-0">룸 뷰 이동</button>
        </div>
      `;
    }).join('');

    const curHeroId = getActiveHeroDef().id;
    const roster30Html = `
      <div class="diary-card space-y-2.5 !p-3.5">
        <div class="flex items-center justify-between gap-2">
          <div class="font-title text-[18px] text-[#1E1B18]">🎨 팝마트 하이브리드 아트토이 30종 도감</div>
          <span class="kw-chip tone-gold">30 / 30</span>
        </div>
        <div class="grid grid-cols-3 gap-2">
          ${(window.ANIMAL_CHARACTER_ROSTER || []).map((ch) => {
            const isPicked = ch.id === curHeroId;
            return `
              <button type="button" data-pick-arttoy="${ch.id}" class="rounded-2xl p-2 border-2 text-center transition-transform active:scale-95 flex flex-col items-center gap-1 ${isPicked ? 'bg-[#FFFBEB] border-[#F59E0B] shadow-md' : 'bg-[#FFFDF7] border-[#E8CCB0]'}">
                ${createHouseholdAvatarSVG(ch.id, 52)}
                <div class="font-title text-[14px] text-[#1E1B18] leading-tight line-clamp-1">${ch.name}</div>
                <span class="px-2 py-0.5 rounded-full font-extrabold text-[12px] bg-[#FEF3C7] text-[#B45309] line-clamp-1">${ch.title}</span>
              </button>
            `;
          }).join('')}
        </div>
      </div>
    `;

    dom.notebookBody.innerHTML = roomsHtml + roster30Html;

    dom.notebookBody.querySelectorAll('[data-nb-room]').forEach((btn) => {
      btn.addEventListener('click', () => {
        dom.notebookModal?.classList.add('hidden');
        focusCameraOnRoom(btn.getAttribute('data-nb-room'));
      });
    });
    dom.notebookBody.querySelectorAll('[data-pick-arttoy]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const cid = btn.getAttribute('data-pick-arttoy');
        selectHeroAnimalId(cid);
        dom.notebookModal?.classList.add('hidden');
        openAnimalSelectModal(false);
      });
    });
  } else if (activeNotebookTab === 'manager') {
    // 🪴 황금 분재 거북소장 급여(Lv.1~Lv.20) & 호실 월세 상한선(Rent Cap) & 사기/태업 인사 관리 센터!
    const b = state.buildings.lot_main;
    b.manager = ensureManagerSchema(b.manager);
    const mgr = b.manager;
    const curDef = getManagerSalaryDef(mgr.salaryLv);
    const nextDef = mgr.salaryLv < 20 ? getManagerSalaryDef(mgr.salaryLv + 1) : null;
    const bonusCost = Math.max(6, curDef.salary * 2);
    const moralePct = Math.round(mgr.morale ?? 100);
    const mgrIconUrls = POPMART_ASSETS?.mgrIconUrls || [];
    const canAffordRaise = nextDef && (state.gold || 0) >= nextDef.raiseCost;
    const canAffordBonus = (state.gold || 0) >= bonusCost;

    const roadmapLevels = [1, 2, 5, 10, 15, 20].map((lv) => getManagerSalaryDef(lv));

    dom.notebookBody.innerHTML = `
      <div class="diary-card space-y-2.5 ${mgr.onStrike ? '!border-2 !border-[#E11D48] !bg-[#FFF1F2]' : '!border-2 !border-[#10B981] !bg-[#F0FDF4]'}">
        <div class="flex items-center gap-3">
          ${createHouseholdAvatarSVG('raccoon_manager', 58)}
          <div class="min-w-0 flex-1">
            <div class="flex items-center gap-1.5 flex-wrap">
              <span class="px-2 py-0.5 rounded-full font-num text-[10.5px] bg-[#065F46] text-[#FFFDF7]">Lv.${curDef.level} / 20</span>
              <span class="font-title text-[15px] text-[#3A2E2B]">${curDef.roleTitle}</span>
            </div>
            <div class="font-body text-[11.5px] font-bold text-[#4B5563] mt-0.5">${curDef.perkDesc}</div>
            <div class="flex items-center gap-1.5 mt-1 flex-wrap">
              <span class="kw-chip tone-coral !text-[10px]">정기 급여 -${curDef.salary}만/주기</span>
              <span class="kw-chip tone-gold !text-[10px]">호실 월세 상한 ${curDef.rentCap.toLocaleString()}만</span>
            </div>
          </div>
        </div>

        <div class="space-y-1 pt-1">
          <div class="flex items-center justify-between text-[11.5px] font-title">
            <span class="${mgr.onStrike ? 'text-[#BE123C]' : 'text-[#065F46]'}">
              ${mgr.onStrike ? '💢 현재 태업(파업) 돌입 중! (전 호실 월세 -50% 연체)' : `🧹 근무 사기(Morale): ${moralePct}% ${(mgr.loyaltyBuffTimer || 0) > 0 ? '· ✨ 광택 충성버프 +15%!' : ''}`}
            </span>
            <span class="text-[#69544C]">${curDef.autoCollect ? '자동수금 ON' : '수동수금 (Lv.5 자동화)'}</span>
          </div>
          <div class="candy-gauge-track !h-2.5">
            <div class="candy-gauge-fill ${mgr.onStrike || moralePct <= 45 ? 'candy-coral' : 'candy-mint'}" style="width:${moralePct}%;"></div>
          </div>
        </div>

        ${nextDef ? `
          <button type="button" id="btn-raise-mgr-salary" class="jelly-action-btn ${canAffordRaise ? 'btn-gold-lip' : 'btn-coral-lip opacity-60'} w-full py-2.5 !text-[12.5px]">
            ${mgrIconUrls[1] ? `<img src="${mgrIconUrls[1]}" alt="" class="toy-ico-img w-5 h-5" />` : createCustomSVGIcon('coin_stack', 17)}
            <span>💰 Lv.${nextDef.level} 급여 인상 (승급비 ${nextDef.raiseCost.toLocaleString()}만 ➔ 한도 ${nextDef.rentCap.toLocaleString()}만!)</span>
          </button>
        ` : `
          <div class="kw-chip tone-gold w-full justify-center py-2">👑 최고 등급 Lv.20 달성! 호실당 25,000만 한도 해금 완료</div>
        `}

        <button type="button" id="btn-give-mgr-bonus" class="jelly-action-btn ${canAffordBonus ? 'btn-mint-lip' : 'btn-sky-lip opacity-60'} w-full py-2 !text-[12px]">
          ${mgrIconUrls[3] ? `<img src="${mgrIconUrls[3]}" alt="" class="toy-ico-img w-4 h-4" />` : createCustomSVGIcon('broom_clean', 16)}
          <span>🎁 특별 성과급 봉투 지급 (${bonusCost}만 · 사기 100% 회복 &amp; 60초 월세 +15%!)</span>
        </button>
      </div>

      <div class="diary-card space-y-2 !p-3">
        <div class="font-title text-[13px] text-[#3A2E2B]">📊 관리인 직급별 호실 월세 상한선(Rent Cap) &amp; 특전 로드맵</div>
        <div class="space-y-1.5">
          ${roadmapLevels.map((rd) => {
            const unlocked = mgr.salaryLv >= rd.level;
            const isCur = mgr.salaryLv === rd.level;
            return `
              <div class="rounded-xl px-2.5 py-1.5 border flex items-center justify-between gap-2 text-[11px] ${isCur ? 'bg-[#FFFBEB] border-[#F59E0B] font-bold' : unlocked ? 'bg-[#ECFDF5] border-[#6EE7B7]' : 'bg-[#F8FAFC] border-[#E2E8F0] opacity-80'}">
                <div class="min-w-0">
                  <span class="font-title text-[#3A2E2B]">Lv.${rd.level} ${rd.roleTitle}</span>
                  <div class="text-[10px] text-[#69544C]">${rd.perkDesc}</div>
                </div>
                <div class="text-right shrink-0 font-num">
                  <div class="text-[#15803D]">한도 ${rd.rentCap.toLocaleString()}만</div>
                  <div class="text-[9.5px] text-[#B91C1C]">급여 -${rd.salary}만</div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;

    dom.notebookBody.querySelector('#btn-raise-mgr-salary')?.addEventListener('click', () => {
      raiseManagerSalaryLevel('lot_main');
    });
    dom.notebookBody.querySelector('#btn-give-mgr-bonus')?.addEventListener('click', () => {
      giveManagerSpecialBonus('lot_main');
    });
  } else {
    const activeLotId = (state.activeTownStage === 2 && state.harborUnlocked) ? 'lot_harbor_main' : 'lot_main';
    const b = state.buildings[activeLotId] || state.buildings.lot_main;
    const infUrls = POPMART_ASSETS?.infraIconUrls || [];
    const infIdxMap = { elevator: 0, recycling: 1, parcel_box: 2, rooftop_garden: 3 };

    const infraCards = Object.values(PUBLIC_INFRA_CATALOG).map((inf) => {
      const owned = !!b.infra[inf.key];
      const icoIdx = infIdxMap[inf.key] ?? 0;
      const thumbHtml = infUrls[icoIdx]
        ? `<div class="w-12 h-12 rounded-2xl bg-[#FFFDF7] border-2 border-[#E8CCB0] flex items-center justify-center shrink-0 overflow-hidden"><img src="${infUrls[icoIdx]}" alt="" class="toy-ico-img w-10 h-10" /></div>`
        : createNotebookArtworkSVG(inf.artKey, 46);
      return `
        <div class="diary-card flex items-center justify-between gap-3">
          <div class="flex items-center gap-3 min-w-0">
            ${thumbHtml}
            <div class="min-w-0">
              <div class="font-title text-[14px] text-[#3A2E2B]">${inf.name}</div>
              <div class="flex items-center gap-1.5 mt-1 flex-wrap">
                <span class="kw-chip tone-mint">전 세대 월세 +${inf.rentBonusPct}%</span>
                <span class="font-body text-[11.5px] font-medium text-[#69544C]">${inf.desc || ''}</span>
              </div>
            </div>
          </div>
          ${owned
            ? `<span class="kw-chip tone-gold shrink-0">${createCustomSVGIcon('sparkle_star', 13)}<span>시공 완료</span></span>`
            : `<button type="button" data-buy-infra="${inf.key}" class="jelly-action-btn btn-gold-lip px-3.5 py-2 shrink-0">${createCustomSVGIcon('coin_stack', 15)}<span>${inf.cost.toLocaleString()}만 시공</span></button>`}
        </div>
      `;
    }).join('');

    const visibleShops = STANDALONE_SHOPS_TEMPLATE.filter((tpl) => tpl.stage !== 2 || state.harborUnlocked);
    const shopCards = visibleShops.map((tpl) => {
      const st = state.standaloneShops?.[tpl.shopId];
      const { visitRev, cycleRev } = calcStandaloneShopStats(tpl.shopId);
      return `
        <div class="diary-card flex items-center justify-between gap-3">
          <div class="flex items-center gap-3 min-w-0">
            <div class="w-12 h-12 rounded-2xl bg-[#FFFDF7] border-2 border-[#E8CCB0] flex items-center justify-center shrink-0">
              ${createCustomSVGIcon(tpl.svgIcon, 28)}
            </div>
            <div class="min-w-0">
              <div class="font-title text-[14px] text-[#3A2E2B]">${tpl.name} (${tpl.engTitle})</div>
              <div class="font-body text-[11.5px] font-semibold text-[#69544C] mt-0.5">
                ${st?.owned ? `직영 운영 중 · 방문 +${visitRev}만 · 주기 +${cycleRev}만` : `미인수 상가 · 직영 인수가 ${tpl.buyCost.toLocaleString()}만`}
              </div>
            </div>
          </div>
          <button type="button" data-goto-shop="${tpl.shopId}" class="jelly-action-btn btn-coral-lip px-3.5 py-2 shrink-0">상가 이동</button>
        </div>
      `;
    }).join('');

    dom.notebookBody.innerHTML = `<div class="space-y-2.5">${infraCards}${shopCards}</div>`;

    dom.notebookBody.querySelectorAll('[data-buy-infra]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = btn.getAttribute('data-buy-infra');
        const inf = PUBLIC_INFRA_CATALOG[key];
        if (!inf || b.infra[key] || !spendGold(inf.cost)) return;
        b.infra[key] = true;
        rebuildPublicInfraAndManager3D(b.lotId);
        updateTopHUDTargets();
        renderNotebookUnifiedBody();
        showToast(`[${inf.name}] 공용 인프라 시공 완료!`, 'mint');
        saveGameState();
      });
    });

    dom.notebookBody.querySelectorAll('[data-goto-shop]').forEach((btn) => {
      btn.addEventListener('click', () => {
        dom.notebookModal?.classList.add('hidden');
        focusCameraOnShop(btn.getAttribute('data-goto-shop'));
      });
    });
  }
}

// --------------------- 입주 세대 모집 모달 (방 럭셔리 등급 ★1~★5 조건 연동!) ---------------------
function openRecruitModal(room) {
  if (!room) return;
  recruitRoomTarget = room;
  rollRecruitCandidates(room);
  openTurntableShowcaseModal('recruit');
}

function rollRecruitCandidates(room) {
  const isHarborSuite = room?.lotId === 'lot_harbor_main';
  const normalKeys = Object.keys(HOUSEHOLD_TYPES).filter((k) => !HOUSEHOLD_TYPES[k]?.isVipTenant && !HOUSEHOLD_TYPES[k]?.isHarborVip);
  const stage1VipKeys = Object.keys(HOUSEHOLD_TYPES).filter((k) => HOUSEHOLD_TYPES[k]?.isVipTenant && !HOUSEHOLD_TYPES[k]?.isHarborVip);
  const harborVipKeys = Object.keys(HOUSEHOLD_TYPES).filter((k) => HOUSEHOLD_TYPES[k]?.isHarborVip);

  recruitCandidates = [];
  const chosenTypes = [];

  if (isHarborSuite) {
    chosenTypes.push(
      harborVipKeys[0] || 'movie_star',
      harborVipKeys[1] || 'fund_manager',
      harborVipKeys[2] || 'cruise_captain',
      stage1VipKeys[1] || 'it_ceo'
    );
  } else {
    // 일반 입주 희망자 2팀(★1 베이직 조건) + 고액 임대료 3~10배 VIP 입주 희망자 2팀(★3 하이엔드 조건)!
    const n1 = normalKeys[Math.floor(Math.random() * normalKeys.length)] || 'student';
    const remNormals = normalKeys.filter((k) => k !== n1);
    const n2 = remNormals[Math.floor(Math.random() * remNormals.length)] || 'newlywed';
    chosenTypes.push(n1, n2, 'streamer', 'it_ceo');
  }

  for (const tKey of chosenTypes) {
    const hDef = HOUSEHOLD_TYPES[tKey];
    if (!hDef) continue;
    const fam = `${FAMILY_LAST_NAMES[Math.floor(Math.random() * FAMILY_LAST_NAMES.length)]}${GIVEN_NAMES[Math.floor(Math.random() * GIVEN_NAMES.length)]} ${hDef.isVipTenant ? 'VIP' : '세대'}`;
    const budget = Math.round(hDef.minRent + Math.random() * (hDef.maxRent - hDef.minRent));
    recruitCandidates.push({ type: tKey, familyName: fam, maxBudget: budget });
  }
}

function renderRecruitCards() {
  if (!dom.recCardsGrid || !recruitRoomTarget) return;
  const meta = ROOM_TYPE_META[recruitRoomTarget.layoutType] || ROOM_TYPE_META.studio;
  const roomStars = calcRoomLuxuryStars(recruitRoomTarget);
  const starStr = '★'.repeat(Math.max(1, roomStars)) + '☆'.repeat(Math.max(0, 5 - Math.max(1, roomStars)));

  const roomSummaryBanner = `
    <div class="diary-subcard !p-2.5 flex items-center justify-between gap-2 bg-[#FFFBEB] border border-[#FCD34D]">
      <div class="font-title text-[12px] text-[#92400E]">현재 ${recruitRoomTarget.name}호 세팅: <b class="text-[#B45309]">${starStr} (★${roomStars})</b></div>
      <span class="kw-chip ${roomStars >= 3 ? 'tone-mint' : 'tone-gold'} !text-[10px] !py-0.5 !px-2">${roomStars >= 3 ? 'VIP 계약 해금!' : '★3+ 시 VIP 해금'}</span>
    </div>
  `;

  const cardsHtml = recruitCandidates.map((cand, idx) => {
    const hDef = HOUSEHOLD_TYPES[cand.type];
    const isMatch = meta.preferredBy.includes(cand.type);
    const reqStars = hDef.minLuxuryStars || (hDef.isVipTenant ? 3 : 1);
    const rankOk = isItemUnlockedByFameRank(hDef);
    const canContract = roomStars >= reqStars && rankOk;

    return `
      <div class="diary-card !p-3 flex flex-col justify-between gap-2 ${hDef.isVipTenant ? '!border-[#F59E0B] !border-2 !bg-[#FFFDF4]' : isMatch ? '!border-[#38E54D] !border-2' : ''}">
        <div class="space-y-1.5">
          <div class="flex items-center justify-between gap-2">
            <div class="flex items-center gap-2 min-w-0">
              ${createHouseholdAvatarSVG(cand.type, 42)}
              <div class="min-w-0">
                <div class="font-title text-[13.5px] text-[#3A2E2B] truncate">${cand.familyName}</div>
                <span class="role-accent-badge mt-0.5" style="background:${hDef.accentHex};">${hDef.label}</span>
              </div>
            </div>
            <span class="kw-chip ${hDef.isVipTenant ? 'tone-gold' : 'tone-cream'} !text-[10px] !py-0.5 !px-2 shrink-0">필요 ★${reqStars}${hDef.unlockRank ? ` · ${hDef.unlockRank}위` : ''}</span>
          </div>
          <div class="flex items-center justify-between gap-1.5 flex-wrap pt-0.5">
            <span class="font-body text-[12px] font-bold text-[#5C4942]">희망 월세 한도: <b class="text-[#15803D] text-[13.5px]">${cand.maxBudget.toLocaleString()}만</b></span>
            ${isMatch ? `<span class="kw-chip tone-mint !text-[9.5px] !py-0.5 !px-1.5">${meta.shortBadge} +15%</span>` : ''}
          </div>
          ${!rankOk ? `
            <div class="rounded-xl px-2.5 py-1.5 bg-[#FFFBEB] border border-[#FDE68A] font-title text-[10.5px] text-[#92400E]">
              🔒 명성 서열 조건: <b>100인 부자 서열 ${hDef.unlockRank}위 이내</b> 달성 시 이 VIP 세입자와 계약할 수 있습니다!
            </div>
          ` : !canContract ? `
            <div class="rounded-xl px-2.5 py-1.5 bg-[#FEF2F2] border border-[#FECACA] font-title text-[10.5px] text-[#B91C1C]">
              🔒 VIP 입주 조건 미충족: 방에 <b>Tier 3+ 하이엔드 침대 & 설비</b>를 세팅해 <b>럭셔리 ★${reqStars}</b>를 달성하세요!
            </div>
          ` : ''}
        </div>
        ${canContract ? `
          <button type="button" data-sign-cand="${idx}" class="jelly-action-btn ${hDef.isVipTenant ? 'btn-gold-lip' : 'btn-coral-lip'} w-full py-2 !text-[12px]">
            ${createCustomSVGIcon('contract_scroll', 15)}
            <span>${hDef.isVipTenant ? '👑 VIP 고액 입주 계약 체결!' : '입주 계약 체결'}</span>
          </button>
        ` : !rankOk ? `
          <button type="button" data-goto-forbes-vip="1" class="jelly-action-btn btn-gold-lip w-full py-1.5 !text-[11.5px]">
            <span>🏆 1:1 결투로 ${hDef.unlockRank}위 돌파하러 가기</span>
          </button>
        ` : `
          <button type="button" data-goto-room-furn="${recruitRoomTarget.id}" class="jelly-action-btn btn-sky-lip w-full py-1.5 !text-[11.5px]">
            <span>🛋️ 가구 세팅으로 ★${reqStars} 맞추기</span>
          </button>
        `}
      </div>
    `;
  }).join('');

  dom.recCardsGrid.innerHTML = roomSummaryBanner + cardsHtml;

  dom.recCardsGrid.querySelectorAll('[data-goto-room-furn]').forEach((btn) => {
    btn.addEventListener('click', () => {
      dom.recruitModal?.classList.add('hidden');
      if (focusedRoomId !== recruitRoomTarget.id) {
        focusCameraOnRoom(recruitRoomTarget.id);
      }
      focusRevealState.revealed = true;
      renderFocusedRoomInspector();
      syncTopBarsByMode();
    });
  });

  dom.recCardsGrid.querySelectorAll('[data-goto-forbes-vip]').forEach((btn) => {
    btn.addEventListener('click', () => {
      dom.recruitModal?.classList.add('hidden');
      enterShowroomFlexDuel('ranked');
    });
  });

  dom.recCardsGrid.querySelectorAll('[data-sign-cand]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const cand = recruitCandidates[Number(btn.getAttribute('data-sign-cand'))];
      if (!cand || !recruitRoomTarget) return;
      const hDef = HOUSEHOLD_TYPES[cand.type];
      const reqStars = hDef?.minLuxuryStars || 1;
      if (calcRoomLuxuryStars(recruitRoomTarget) < reqStars) {
        showToast(`럭셔리 ★${reqStars} 이상 가구 세팅이 필요합니다!`, 'coral');
        return;
      }
      recruitRoomTarget.household = {
        type: cand.type,
        familyName: cand.familyName,
        maxBudget: cand.maxBudget,
        happiness: hDef?.isVipTenant ? 88 : 65
      };
      recruitRoomTarget.rentTimer = 4.0;
      dom.recruitModal?.classList.add('hidden');
      syncBuildingResidents3D(recruitRoomTarget.lotId);
      updateTopHUDTargets();
      if (focusRevealState.revealed) renderFocusedRoomInspector();
      syncTopBarsByMode();
      showToast(`${recruitRoomTarget.name}호에 [${cand.familyName}] 입주 계약 완료! (한도 ${cand.maxBudget}만)`, 'gold');
      saveGameState();
    });
  });
}

// --------------------- [요구사항 5] 실시간 3D 착공 현장(비계 · 회전 노란 타워크레인 · 안전모 동물 인부 · 0%➔100% 공정률) & 증축 관리 ---------------------
function create3DLiveConstructionRig(isRoomFloor = false, spanW = 10.2, spanD = 7.6, spanH = 4.6) {
  const grp = new THREE.Group();
  const craneYellow = makeClayMat(0xFACC15, { roughness: 0.36, metalness: 0.18 });
  const steelMat = makeClayMat(0x64748B, { roughness: 0.42, metalness: 0.35 });
  const woodPlankMat = MAT.woodWarm;
  const coneOrange = makeClayMat(0xF97316, { roughness: 0.48 });

  // 1) 3D 철제 파이프 & 원목 발판 비계(Scaffolding) 구조물
  const scafGroup = new THREE.Group();
  grp.add(scafGroup);
  const hw = spanW * 0.48;
  const hd = spanD * 0.48;
  const postCoords = isRoomFloor
    ? [[-hw, hd], [0, hd], [hw, hd]]
    : [[-hw, -hd], [hw, -hd], [-hw, hd], [hw, hd], [0, hd]];
  for (const [px, pz] of postCoords) {
    const pole = new THREE.Mesh(GEO.cyl, steelMat);
    pole.scale.set(0.11, spanH + 0.8, 0.11);
    pole.position.set(px, (spanH + 0.8) * 0.5, pz);
    scafGroup.add(pole);
  }
  for (const ly of [1.35, 2.75, Math.min(spanH, 4.05)]) {
    scafGroup.add(createRoundedToyMesh(spanW + 0.3, 0.12, 0.72, woodPlankMat, 0, ly, hd, 0.03));
    if (!isRoomFloor) {
      scafGroup.add(createRoundedToyMesh(spanW + 0.3, 0.1, 0.12, steelMat, 0, ly + 0.5, -hd, 0.02));
      scafGroup.add(createRoundedToyMesh(0.12, 0.1, spanD, steelMat, -hw, ly + 0.5, 0, 0.02));
      scafGroup.add(createRoundedToyMesh(0.12, 0.1, spanD, steelMat, hw, ly + 0.5, 0, 0.02));
    }
    // X자 대각 가새 파이프
    const brace1 = createRoundedToyMesh(spanW * 0.45, 0.08, 0.08, craneYellow, -hw * 0.48, ly - 0.55, hd + 0.08, 0.02);
    brace1.rotation.z = 0.42;
    const brace2 = createRoundedToyMesh(spanW * 0.45, 0.08, 0.08, craneYellow, hw * 0.48, ly - 0.55, hd + 0.08, 0.02);
    brace2.rotation.z = -0.42;
    scafGroup.add(brace1, brace2);
  }

  // 공정률(0% -> 100%)에 따라 단계별로 솟아오르는 내부 골조 블록
  const risingCore = createRoundedToyMesh(spanW * 0.82, spanH * 0.88, spanD * 0.78, MAT.dollhouseCutaway || MAT.cream, 0, (spanH * 0.88) * 0.5, 0, 0.12);
  risingCore.scale.y = 0.08;
  grp.add(risingCore);

  // 2) 팔(Jib)이 360도 회전하는 노란색 3D 타워크레인 (Yellow 3D Tower Crane)
  const mastH = isRoomFloor ? (spanH + 5.8) : 11.5;
  const mastX = isRoomFloor ? (hw + 1.35) : (hw + 1.6);
  const mastZ = isRoomFloor ? (hd + 0.9) : (-hd * 0.4);
  const craneRoot = new THREE.Group();
  craneRoot.position.set(mastX, 0, mastZ);
  grp.add(craneRoot);

  craneRoot.add(createRoundedToyMesh(1.6, 0.36, 1.6, steelMat, 0, 0.18, 0, 0.06));
  for (const [mx, mz] of [[-0.42, -0.42], [0.42, -0.42], [-0.42, 0.42], [0.42, 0.42]]) {
    craneRoot.add(createRoundedToyMesh(0.16, mastH, 0.16, craneYellow, mx, mastH * 0.5, mz, 0.03));
  }
  for (let y = 1.2; y < mastH; y += 1.45) {
    craneRoot.add(createRoundedToyMesh(1.02, 0.12, 1.02, craneYellow, 0, y, 0, 0.02));
  }

  const jibPivot = new THREE.Group();
  jibPivot.position.set(0, mastH, 0);
  craneRoot.add(jibPivot);

  // 조종석 캐빈 + 긴 회전 지브 팔 + 카운터웨이트 + 트롤리 후크 & 매달린 원목 자재
  jibPivot.add(createRoundedToyMesh(1.15, 1.1, 1.15, craneYellow, 0, 0.55, 0.25, 0.08));
  jibPivot.add(createRoundedToyMesh(0.95, 0.65, 0.2, MAT.screenCyan, 0, 0.62, 0.82, 0.03));
  jibPivot.add(createRoundedToyMesh(9.6, 0.42, 0.56, craneYellow, -2.4, 0.85, 0, 0.06));
  jibPivot.add(createRoundedToyMesh(1.65, 0.92, 0.95, steelMat, 2.2, 0.58, 0, 0.08));
  const peakSpire = new THREE.Mesh(new THREE.ConeGeometry(0.45, 1.6, 4), craneYellow);
  peakSpire.position.set(0, 1.85, 0);
  peakSpire.rotation.y = Math.PI * 0.25;
  jibPivot.add(peakSpire);

  const hookGroup = new THREE.Group();
  hookGroup.position.set(-4.8, 0.65, 0);
  const wire = new THREE.Mesh(GEO.cyl, steelMat);
  wire.scale.set(0.05, 3.2, 0.05);
  wire.position.y = -1.6;
  const loadBeam = createRoundedToyMesh(1.85, 0.48, 0.82, MAT.pureGold24k || woodPlankMat, 0, -3.35, 0, 0.06);
  hookGroup.add(wire, loadBeam);
  jibPivot.add(hookGroup);

  // 3) 노란 안전모(Hardhat)를 쓰고 3D 망치질을 하는 동물 현장 인부!
  const worker = createChibiPerson3D('manager', null, 3);
  worker.scale.setScalar(1.08);
  worker.position.set(-1.1, 0.18, hd + 0.72);
  worker.rotation.y = Math.PI;
  const hardhat = new THREE.Group();
  const hatDome = new THREE.Mesh(new THREE.SphereGeometry(0.46, 18, 14, 0, Math.PI * 2, 0, Math.PI * 0.52), craneYellow);
  hatDome.position.set(0, 0.22, 0);
  const hatBrim = createRoundedToyMesh(0.98, 0.08, 1.06, craneYellow, 0, 0.21, 0.06, 0.03);
  hardhat.add(hatDome, hatBrim);
  if (worker.userData?.head) {
    worker.userData.head.add(hardhat);
  } else {
    hardhat.position.y = 1.48;
    worker.add(hardhat);
  }
  const hammerGrp = new THREE.Group();
  hammerGrp.add(createRoundedToyMesh(0.08, 0.48, 0.08, woodPlankMat, 0, -0.18, 0.18, 0.02));
  hammerGrp.add(createRoundedToyMesh(0.28, 0.18, 0.18, steelMat, 0, -0.38, 0.22, 0.03));
  if (worker.userData?.armR) {
    worker.userData.armR.add(hammerGrp);
  }
  grp.add(worker);

  // 전면 안전 라바콘 2개 + 팝마트 3D 공사 안내 입체 현판
  for (const cx of [-2.6, 2.2]) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.26, 0.68, 12), coneOrange);
    cone.position.set(cx, 0.34, hd + 1.05);
    const stripe = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.035, 8, 16), MAT.white);
    stripe.rotation.x = Math.PI * 0.5;
    stripe.position.set(cx, 0.36, hd + 1.05);
    grp.add(cone, stripe);
  }
  const beacon = new THREE.Mesh(GEO.sphere, MAT.supercarRed || coneOrange);
  beacon.scale.setScalar(0.2);
  beacon.position.set(0, 2.75, 0);
  jibPivot.add(beacon);

  if (POPMART_ASSETS?.buildings?.propConstructionCraneMat) {
    const craneSign = new THREE.Mesh(new THREE.PlaneGeometry(2.15, 2.15), POPMART_ASSETS.buildings.propConstructionCraneMat);
    craneSign.name = 'popmart_construction_emblem';
    craneSign.position.set(1.25, 1.48, hd + 1.12);
    grp.add(craneSign);
  }

  return { grp, scafGroup, risingCore, jibPivot, hookGroup, worker, mastH };
}

function syncPocketBuildBadge() {
  const activeCount = Object.keys(constructionState.sites).length;
  const badge = document.getElementById('stamp-build-badge');
  const sub = document.getElementById('pocket-build-subtext');
  if (badge) {
    badge.classList.toggle('hidden', activeCount <= 0);
    if (activeCount > 0) badge.textContent = `${activeCount}건 시공중`;
  }
  if (sub) {
    if (activeCount > 0) {
      const firstSite = Object.values(constructionState.sites)[0];
      sub.textContent = `🏗️ ${firstSite.title} 공정률 ${Math.floor(firstSite.progress)}% 진행 중!`;
    } else {
      sub.textContent = '3D 타워크레인 착공 · 공정률 확인';
    }
  }
}

function startLive3DConstructionJob(opt) {
  // opt: { jobKey, kind: 'lot' | 'room', lotId, devType, roomId, title, durationSec, wx, wy, wz, spanW, spanD, spanH }
  if (constructionState.sites[opt.jobKey]) {
    showToast('이미 해당 현장에서 타워크레인 공사가 진행 중입니다!', 'gold');
    return;
  }

  if (opt.kind === 'lot') {
    clearLot3D(opt.lotId);
  }

  const rig = create3DLiveConstructionRig(opt.kind === 'room', opt.spanW || 10.4, opt.spanD || 7.8, opt.spanH || 4.8);
  rig.grp.position.set(opt.wx, opt.wy, opt.wz);
  scene.add(rig.grp);

  // 3D 현장 상단에 실시간 투영되는 공정률(0% ➔ 100%) 프로그레스 바 & [⚡ 특별 야근 투입 (즉시 완공)] 버튼 생성!
  const layer = document.getElementById('construction-overlay-layer');
  let pinEl = null;
  if (layer) {
    pinEl = document.createElement('div');
    pinEl.className = 'construction-prog-pin';
    pinEl.innerHTML = `
      <div class="flex items-center justify-between gap-2 text-[11.5px] font-title text-[#2C221E]">
        <span class="truncate">🏗️ ${opt.title}</span>
        <span data-cprog-pct class="font-num text-[#B45309] shrink-0">0%</span>
      </div>
      <div class="candy-gauge-track !h-2.5 mt-1">
        <div data-cprog-fill class="candy-gauge-fill candy-gold" style="width: 2%;"></div>
      </div>
      <button type="button" data-crush-job="${opt.jobKey}" class="construction-rush-btn">
        ⚡ 특별 야근 투입 (즉시 완공)
      </button>
    `;
    pinEl.addEventListener('pointerdown', (e) => e.stopPropagation());
    pinEl.addEventListener('pointerup', (e) => e.stopPropagation());
    pinEl.querySelector('[data-crush-job]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      completeLive3DConstructionJob(opt.jobKey, true);
    });
    layer.appendChild(pinEl);
  }

  const siteObj = {
    ...opt,
    progress: 2,
    durationSec: opt.durationSec || 20.0,
    dustAccum: 0,
    rig,
    pinEl
  };
  constructionState.sites[opt.jobKey] = siteObj;
  syncPocketBuildBadge();

  // 카메라를 타워크레인 착공 현장으로 부드럽게 이동시켜 생생한 비계·크레인 회전·동물 망치질을 즉시 감상!
  if (!driveState.active && !fpState.active && !duelState.active) {
    if (focusedRoomId) exitRoomFocusMode();
    if (focusedShopId || focusedFirstFloorShopId) exitShopFocusMode();
    startSmoothCameraTween(
      new THREE.Vector3(opt.wx + 18.5, opt.wy + 16.5, opt.wz + 26.5),
      new THREE.Vector3(opt.wx, opt.wy + 3.2, opt.wz),
      1.18,
      0.55,
      null
    );
  }

  playGoldenBellSound();
  spawnPoofParticles3D(opt.wx, opt.wy + 1.2, opt.wz, 0xFACC15, 14);
  showToast(`🏗️ [${opt.title}] 3D 타워크레인 착공 돌입! (0% ➔ 100% 단계별 시공)`, 'gold');
}

function completeLive3DConstructionJob(jobKey, isInstantRush = false) {
  const site = constructionState.sites[jobKey];
  if (!site) return;

  if (site.rig?.grp) scene.remove(site.rig.grp);
  if (site.pinEl) site.pinEl.remove();
  delete constructionState.sites[jobKey];

  if (site.kind === 'room') {
    const rm = findRoomById(site.roomId);
    if (rm) {
      rm.unlocked = true;
      buildSingleLot3D(rm.lotId);
    }
  } else if (site.kind === 'lot') {
    const lot = state.lots.find((l) => l.lotId === site.lotId);
    const cat = DEVELOPMENT_CATALOG[site.devType];
    if (lot && cat) {
      lot.owned = true;
      lot.devType = site.devType;
      lot.title = cat.name;
      if (cat.isResidential) {
        state.buildings[lot.lotId] = makeResidentialBuilding(lot.lotId, site.devType, cat.name, false);
      } else {
        state.developments[lot.lotId] = { lotId: lot.lotId, devType: site.devType, timer: cat.cycleSec };
      }
      buildSingleLot3D(lot.lotId);
    }
  }

  syncPocketBuildBadge();
  playGoldenBellSound();
  spawnShockwaveRing3D(site.wx, site.wy + 0.4, site.wz, 0xFFD700, 8.5);
  spawnPoofParticles3D(site.wx, site.wy + 3.0, site.wz, 0xFFD700, 18);
  updateTopHUDTargets();
  if (!dom.lotDevModal?.classList.contains('hidden')) {
    openLotDevModal(devModalLotId);
  }
  showToast(
    isInstantRush
      ? `⚡ 특별 야근 투입! [${site.title}] 공정률 100% 즉시 완공 완료!!`
      : `🎉 [${site.title}] 100% 완공! 신규 임대 및 시너지 수익이 개시됩니다!`,
    'gold'
  );
  saveGameState();
}

function tickLive3DConstructionSites(dt, elapsed) {
  const keys = Object.keys(constructionState.sites);
  if (keys.length === 0) return;

  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const inHiddenOverlay = titleScreenState.active || guidedTourState.active || duelState.active || fpState.active;

  for (const jobKey of keys) {
    const site = constructionState.sites[jobKey];
    if (!site) continue;

    site.progress = Math.min(100, site.progress + (100 / Math.max(4, site.durationSec)) * dt);
    const ratio = site.progress / 100;

    // 1) 노란 3D 타워크레인 팔(Jib) 회전 & 후크 상하 인양 모션
    if (site.rig?.jibPivot) {
      site.rig.jibPivot.rotation.y = Math.sin(elapsed * 1.15 + site.wx * 0.1) * 0.95;
    }
    if (site.rig?.hookGroup) {
      site.rig.hookGroup.position.y = 0.65 + Math.sin(elapsed * 2.4) * 0.55;
    }
    // 2) 공정률에 비례하여 실제 건물 골조가 비계 안에서 쑥쑥 솟아오름!
    if (site.rig?.risingCore) {
      site.rig.risingCore.scale.y = 0.1 + ratio * 0.9;
    }
    // 3) 안전모 동물 인부의 신나는 망치질 & 흙먼지/나무칩 파티클!
    if (site.rig?.worker?.userData?.armR) {
      site.rig.worker.userData.armR.rotation.x = -0.95 + Math.sin(elapsed * 15.0) * 0.65;
      site.rig.worker.position.y = 0.18 + Math.abs(Math.sin(elapsed * 7.5)) * 0.08;
    }
    site.dustAccum += dt;
    if (site.dustAccum >= 0.62) {
      site.dustAccum = 0;
      spawnPoofParticles3D(site.wx - 1.0, site.wy + 1.1, site.wz + (site.spanD || 7.6) * 0.45, 0xE7D5C0, 4);
    }

    // 4) 상단 실시간 공정률(0% -> 100%) 프로그레스 핀 화면 좌표 투영 업데이트
    if (site.pinEl) {
      const pctTxt = site.pinEl.querySelector('[data-cprog-pct]');
      const fillBar = site.pinEl.querySelector('[data-cprog-fill]');
      const roundedPct = Math.min(100, Math.floor(site.progress));
      if (pctTxt) pctTxt.textContent = `${roundedPct}%`;
      if (fillBar) fillBar.style.width = `${roundedPct}%`;

      const lotDef = state.lots.find((l) => l.lotId === site.lotId);
      const inSameWorld = (lotDef?.stage === 2) === (WorldManager.currentStage === 2);
      if (inHiddenOverlay || !inSameWorld) {
        site.pinEl.style.display = 'none';
      } else {
        const pt = projectWorldToScreen(site.wx, site.wy + (site.spanH || 4.8) + 3.2, site.wz);
        if (!pt.visible || pt.x < 40 || pt.x > vw - 40 || pt.y < 60 || pt.y > vh - 40) {
          site.pinEl.style.display = 'none';
        } else {
          site.pinEl.style.display = 'block';
          site.pinEl.style.left = `${pt.x}px`;
          site.pinEl.style.top = `${pt.y}px`;
        }
      }
    }

    if (site.progress >= 100) {
      completeLive3DConstructionJob(jobKey, false);
    }
  }
  syncPocketBuildBadge();
}

function openLotDevModal(lotId = null) {
  if (!dom.devCardsGrid) return;
  closeAllModalsImmediate('lot-dev-modal');
  devModalLotId = lotId;

  const targetLot = lotId ? state.lots.find((l) => l.lotId === lotId) : null;
  if (dom.devLotBadge) {
    dom.devLotBadge.textContent = targetLot ? targetLot.name : '통합 증축 · 착공 공정 관리';
  }

  const htmlBlocks = [];

  // 1) 현재 실시간 시공 중인 3D 타워크레인 공정 현황 카드
  const activeSites = Object.values(constructionState.sites);
  if (activeSites.length > 0) {
    htmlBlocks.push(`
      <div class="diary-card !bg-[#FFFBEB] !border-2 !border-[#F59E0B] space-y-2">
        <div class="font-title text-[13.5px] text-[#92400E]">🏗️ 실시간 3D 타워크레인 시공 현장 (${activeSites.length}건)</div>
        ${activeSites.map((s) => `
          <div class="rounded-xl bg-white p-2.5 border border-[#FDE68A] space-y-1.5">
            <div class="flex items-center justify-between text-[12px] font-title">
              <span>${s.title}</span>
              <span class="font-num text-[#B45309]">${Math.floor(s.progress)}%</span>
            </div>
            <div class="candy-gauge-track !h-2.5">
              <div class="candy-gauge-fill candy-gold" style="width:${Math.floor(s.progress)}%;"></div>
            </div>
            <button type="button" data-modal-rush="${s.jobKey}" class="jelly-action-btn btn-gold-lip w-full py-1.5 !text-[11.5px]">
              <span>⚡ 특별 야근 투입 (즉시 완공)</span>
            </button>
          </div>
        `).join('')}
      </div>
    `);
  }

  // 2) 메인 빌딩 / 하버 호텔 잠긴 층·호실 증축 발주 카드 (수첩 [🏗️ 빌딩 증축 · 착공 공정 관리] 진입 시 표시)
  const activeBldId = WorldManager.currentStage === 2 ? 'lot_harbor_main' : 'lot_main';
  const activeBld = state.buildings[activeBldId];
  const bldLot = state.lots.find((l) => l.lotId === activeBldId);
  if (!targetLot || targetLot.lotId === activeBldId) {
    const lockedRooms = (activeBld?.rooms || []).filter((r) => !r.unlocked && !constructionState.sites[`room_${r.id}`]);
    if (lockedRooms.length > 0) {
      htmlBlocks.push(`
        <div class="diary-card space-y-2">
          <div class="font-title text-[13.5px] text-[#3A2E2B]">🏢 [${activeBld.title}] 상층부 호실 증축 착공</div>
          ${lockedRooms.map((rm) => {
            const meta = ROOM_TYPE_META[rm.layoutType] || ROOM_TYPE_META.studio;
            const cost = rm.unlockCost || 180;
            return `
              <div class="rounded-xl bg-[#F8FAFC] border border-[#CBD5E1] p-2.5 flex items-center justify-between gap-2">
                <div>
                  <div class="font-title text-[12.5px] text-[#2C221E]">${rm.name}호 · ${meta.badge}</div>
                  <div class="font-body text-[10.5px] font-bold text-[#64748B]">3D 비계 &amp; 타워크레인 시공</div>
                </div>
                <button type="button" data-expand-room-id="${rm.id}" class="jelly-action-btn btn-sky-lip !py-1.5 !px-3 !text-[11.5px] shrink-0">
                  <span>🏗️ ${cost}만 착공</span>
                </button>
              </div>
            `;
          }).join('')}
        </div>
      `);
    }
  }

  // 3) 특정 외곽 부지 또는 전체 미개발 부지 매입 & 착공 카드
  const candidateLots = (targetLot && targetLot.lotId !== 'lot_main' && targetLot.lotId !== 'lot_harbor_main')
    ? [targetLot]
    : state.lots.filter((l) => l.lotId !== 'lot_main' && l.lotId !== 'lot_harbor_main' && (WorldManager.currentStage === 2 ? l.stage === 2 : l.stage !== 2));

  for (const lot of candidateLots) {
    if (constructionState.sites[`lot_${lot.lotId}`]) continue;
    if (!lot.owned) {
      htmlBlocks.push(`
        <div class="diary-card p-3 space-y-2">
          <div class="flex items-center justify-between">
            <span class="font-title text-[14px] text-[#3A2E2B]">🌱 ${lot.name} 토지 매입</span>
            <span class="kw-chip tone-gold">${lot.landPrice.toLocaleString()}만</span>
          </div>
          <div class="font-body text-[11.5px] font-semibold text-[#69544C]">매입 후 3D 타워크레인을 투입해 발전소·농장·주상복합을 착공합니다.</div>
          <button type="button" data-buy-lot-id="${lot.lotId}" class="jelly-action-btn btn-gold-lip w-full py-2 !text-[12px]">
            ${createCustomSVGIcon('coin_stack', 16)}
            <span>${lot.landPrice.toLocaleString()}만 토지 매입하기</span>
          </button>
        </div>
      `);
    } else if (!lot.devType) {
      const devKeys = ['solar_plant', 'urban_farm', 'sakura_park', 'bakery_cafe', 'mixed_2'];
      htmlBlocks.push(`
        <div class="diary-card p-3 space-y-2">
          <div class="font-title text-[14px] text-[#3A2E2B]">🏗️ [${lot.name}] 착공 시설 발주</div>
          <div class="space-y-2">
            ${devKeys.map((dk) => {
              const cat = DEVELOPMENT_CATALOG[dk];
              const devUrls = POPMART_ASSETS?.devLotIconUrls || [];
              const devIdxMap = { solar_plant: 0, urban_farm: 1, sakura_park: 2, bakery_cafe: 3, mixed_2: 3 };
              const devThumb = devUrls[devIdxMap[dk] ?? 0]
                ? `<div class="w-9 h-9 rounded-xl bg-[#FFFDF7] border border-[#E8CCB0] flex items-center justify-center shrink-0 overflow-hidden"><img src="${devUrls[devIdxMap[dk] ?? 0]}" alt="" class="toy-ico-img w-8 h-8" /></div>`
                : createNotebookArtworkSVG(cat.artKey, 34);
              return `
                <div class="rounded-xl bg-[#FFFDF9] border border-[#E8D5C0] p-2 flex items-center justify-between gap-2">
                  <div class="flex items-center gap-2 min-w-0">
                    ${devThumb}
                    <div class="min-w-0">
                      <div class="font-title text-[12.5px] text-[#3A2E2B] truncate">${cat.name}</div>
                      <div class="font-body text-[10.5px] font-bold text-[#15803D]">시너지 +${cat.rentSynergyPct}%</div>
                    </div>
                  </div>
                  <button type="button" data-build-lot="${lot.lotId}" data-build-dev="${dk}" class="jelly-action-btn btn-coral-lip !py-1.5 !px-3 !text-[11.5px] shrink-0">
                    <span>🏗️ ${cat.buildCost.toLocaleString()}만 착공</span>
                  </button>
                </div>
              `;
            }).join('')}
          </div>
        </div>
      `);
    }
  }

  if (htmlBlocks.length === 0) {
    htmlBlocks.push(`
      <div class="diary-card p-4 text-center font-title text-[13.5px] text-[#15803D]">
        ✨ 현재 월드의 모든 호실 증축 및 부지 착공이 100% 완료되었습니다!
      </div>
    `);
  }

  dom.devCardsGrid.innerHTML = htmlBlocks.join('');

  dom.devCardsGrid.querySelectorAll('[data-modal-rush]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const jk = btn.getAttribute('data-modal-rush');
      completeLive3DConstructionJob(jk, true);
    });
  });

  dom.devCardsGrid.querySelectorAll('[data-expand-room-id]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const rid = btn.getAttribute('data-expand-room-id');
      const rm = findRoomById(rid);
      if (!rm || !bldLot) return;
      const cost = rm.unlockCost || 180;
      if (!spendGold(cost)) return;
      dom.lotDevModal?.classList.add('hidden');
      startLive3DConstructionJob({
        jobKey: `room_${rm.id}`,
        kind: 'room',
        lotId: rm.lotId,
        roomId: rm.id,
        title: `${rm.name}호 증축 공사`,
        durationSec: 18.0,
        wx: bldLot.x + rm.lx,
        wy: rm.ly,
        wz: bldLot.z + rm.lz,
        spanW: rm.rw * 0.92,
        spanD: rm.rd * 0.92,
        spanH: rm.rh
      });
      saveGameState();
    });
  });

  dom.devCardsGrid.querySelectorAll('[data-buy-lot-id]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const lid = btn.getAttribute('data-buy-lot-id');
      const lot = state.lots.find((l) => l.lotId === lid);
      if (!lot || !spendGold(lot.landPrice)) return;
      lot.owned = true;
      ensureLotOverlayBadge(lot.lotId);
      openLotDevModal(lid);
      showToast(`[${lot.name}] 토지 매입 완료! 이제 착공할 건물을 발주하세요!`, 'gold');
      saveGameState();
    });
  });

  dom.devCardsGrid.querySelectorAll('[data-build-dev]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const lid = btn.getAttribute('data-build-lot');
      const dk = btn.getAttribute('data-build-dev');
      const lot = state.lots.find((l) => l.lotId === lid);
      const cat = DEVELOPMENT_CATALOG[dk];
      if (!lot || !cat || !spendGold(cat.buildCost)) return;
      dom.lotDevModal?.classList.add('hidden');
      startLive3DConstructionJob({
        jobKey: `lot_${lot.lotId}`,
        kind: 'lot',
        lotId: lot.lotId,
        devType: dk,
        title: `${lot.name} · ${cat.name}`,
        durationSec: 20.0,
        wx: lot.x,
        wy: 0.12,
        wz: lot.z,
        spanW: cat.isResidential ? 18.0 : 10.6,
        spanD: 8.2,
        spanH: cat.isResidential ? 9.5 : 4.8
      });
      saveGameState();
    });
  });

  dom.lotDevModal?.classList.remove('hidden');
}

function openRenameModal(lotId) {
  const b = state.buildings[lotId];
  if (!b) return;
  renameTargetLotId = lotId;
  if (dom.inputBuildingName) dom.inputBuildingName.value = b.title;
  if (dom.renamePresetsRow) {
    dom.renamePresetsRow.innerHTML = BUILDING_NAME_PRESETS.map((p) => `
      <button type="button" data-preset-name="${p}" class="kw-chip tone-gold cursor-pointer">${p}</button>
    `).join('');
    dom.renamePresetsRow.querySelectorAll('[data-preset-name]').forEach((btn) => {
      btn.addEventListener('click', () => {
        if (dom.inputBuildingName) dom.inputBuildingName.value = btn.getAttribute('data-preset-name');
      });
    });
  }
  dom.renameModal?.classList.remove('hidden');
}

