function removeWhiteBackground(img, mode = 'single', threshold = 242) {
  const w = Math.max(1, img.naturalWidth || img.width || 512);
  const h = Math.max(1, img.naturalHeight || img.height || 512);
  const cv = document.createElement('canvas');
  cv.width = w;
  cv.height = h;
  const ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(img, 0, 0, w, h);

  const imgData = ctx.getImageData(0, 0, w, h);
  const data = imgData.data;
  const total = w * h;
  const visited = new Uint8Array(total);
  const queue = new Int32Array(total);
  let head = 0;
  let tail = 0;

  const isBgWhite = (idx4) => {
    if (data[idx4 + 3] === 0) return false;
    const r = data[idx4];
    const g = data[idx4 + 1];
    const b = data[idx4 + 2];
    if (r > threshold && g > threshold && b > threshold) return true;
    if (mode === 'vfx') {
      const maxC = Math.max(r, g, b);
      const minC = Math.min(r, g, b);
      // 스튜디오 바닥 연회색 그림자(채도가 거의 없는 무채색 밝은 회색)까지 깔끔하게 투명화!
      if (minC > 162 && (maxC - minC) < 24) return true;
    }
    return false;
  };

  const trySeed = (x, y) => {
    if (x < 0 || x >= w || y < 0 || y >= h) return;
    const p = y * w + x;
    if (visited[p]) return;
    const i4 = p * 4;
    if (isBgWhite(i4)) {
      visited[p] = 1;
      queue[tail++] = p;
    }
  };

  for (let x = 0; x < w; x++) {
    trySeed(x, 0);
    trySeed(x, 1);
    trySeed(x, h - 1);
    trySeed(x, h - 2);
  }
  for (let y = 0; y < h; y++) {
    trySeed(0, y);
    trySeed(1, y);
    trySeed(w - 1, y);
    trySeed(w - 2, y);
  }

  if (mode === '4frame') {
    for (const frac of [0.25, 0.5, 0.75]) {
      const cx = Math.floor(w * frac);
      for (let y = 0; y < h; y++) {
        trySeed(cx - 1, y);
        trySeed(cx, y);
        trySeed(cx + 1, y);
      }
    }
  } else if (mode === '2x2') {
    const mx = Math.floor(w * 0.5);
    const my = Math.floor(h * 0.5);
    for (let y = 0; y < h; y++) {
      trySeed(mx - 1, y);
      trySeed(mx, y);
      trySeed(mx + 1, y);
    }
    for (let x = 0; x < w; x++) {
      trySeed(x, my - 1);
      trySeed(x, my);
      trySeed(x, my + 1);
    }
  }

  while (head < tail) {
    const p = queue[head++];
    const i4 = p * 4;
    data[i4 + 3] = 0;

    const px = p % w;
    const py = (p - px) / w;

    if (px > 0) {
      const np = p - 1;
      if (!visited[np] && isBgWhite(np * 4)) { visited[np] = 1; queue[tail++] = np; }
    }
    if (px + 1 < w) {
      const np = p + 1;
      if (!visited[np] && isBgWhite(np * 4)) { visited[np] = 1; queue[tail++] = np; }
    }
    if (py > 0) {
      const np = p - w;
      if (!visited[np] && isBgWhite(np * 4)) { visited[np] = 1; queue[tail++] = np; }
    }
    if (py + 1 < h) {
      const np = p + w;
      if (!visited[np] && isBgWhite(np * 4)) { visited[np] = 1; queue[tail++] = np; }
    }
  }

  // 팔다리 사이 닫힌 순백색(#FFFFFF 부근 >=251) 홀 제거 및 경계 안티앨리어싱 소프트 페더링
  for (let y = 1; y < h - 1; y++) {
    const row = y * w;
    for (let x = 1; x < w - 1; x++) {
      const p = row + x;
      if (visited[p]) continue;
      const i4 = p * 4;
      const r = data[i4];
      const g = data[i4 + 1];
      const b = data[i4 + 2];
      if (r >= 251 && g >= 251 && b >= 251) {
        data[i4 + 3] = 0;
        visited[p] = 1;
        continue;
      }
      if (visited[p - 1] || visited[p + 1] || visited[p - w] || visited[p + w]) {
        const minCh = Math.min(r, g, b);
        if (minCh > 228) {
          const softFactor = Math.max(0.08, Math.min(1, (245 - minCh) / 17));
          data[i4 + 3] = Math.round(data[i4 + 3] * softFactor);
        }
      }
    }
  }

  ctx.putImageData(imgData, 0, 0);
  return cv;
}

function cropTrimmedRegionToCanvas(srcCanvas, sx, sy, sw, sh, outW = 512, outH = 512, alignBottom = false) {
  const sCtx = srcCanvas.getContext('2d', { willReadFrequently: true });
  const sub = sCtx.getImageData(sx, sy, sw, sh);
  const d = sub.data;

  // 미세 먼지 픽셀(주변 5x5 내 불투명 이웃이 6개 미만인 고립 점) 제거로 판다·양 크기 정규화 완벽 보장!
  for (let y = 2; y < sh - 2; y++) {
    const row = y * sw;
    for (let x = 2; x < sw - 2; x++) {
      const idx = (row + x) * 4;
      if (d[idx + 3] === 0) continue;
      let neighbors = 0;
      for (let dy = -2; dy <= 2; dy++) {
        const nr = (y + dy) * sw;
        for (let dx = -2; dx <= 2; dx++) {
          if (d[(nr + x + dx) * 4 + 3] > 32) neighbors++;
        }
      }
      if (neighbors < 6) {
        d[idx + 3] = 0;
      }
    }
  }
  sCtx.putImageData(sub, sx, sy);

  let minX = sw;
  let minY = sh;
  let maxX = -1;
  let maxY = -1;

  for (let y = 0; y < sh; y++) {
    const row = y * sw;
    for (let x = 0; x < sw; x++) {
      if (d[(row + x) * 4 + 3] > 28) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }

  const out = document.createElement('canvas');
  out.width = outW;
  out.height = outH;
  const oCtx = out.getContext('2d');
  oCtx.imageSmoothingEnabled = true;
  oCtx.imageSmoothingQuality = 'high';

  if (maxX < minX || maxY < minY) {
    oCtx.drawImage(srcCanvas, sx, sy, sw, sh, 0, 0, outW, outH);
    return out;
  }

  const bw = Math.max(1, maxX - minX + 1);
  const bh = Math.max(1, maxY - minY + 1);
  const padFrac = alignBottom ? 0.88 : 0.88;
  const scale = Math.min((outW * padFrac) / bw, (outH * padFrac) / bh);
  const dw = bw * scale;
  const dh = bh * scale;
  const dx = (outW - dw) * 0.5;
  const dy = alignBottom ? (outH * 0.94 - dh) : ((outH - dh) * 0.5);

  oCtx.drawImage(srcCanvas, sx + minX, sy + minY, bw, bh, dx, dy, dw, dh);
  return out;
}

function normalize4FrameSpriteSheet(cleanCanvas) {
  const w = cleanCanvas.width;
  const h = cleanCanvas.height;
  const colW = Math.floor(w / 4);
  const cellW = 512;
  const cellH = 600;

  const master = document.createElement('canvas');
  master.width = cellW * 4;
  master.height = cellH;
  const mCtx = master.getContext('2d');
  mCtx.imageSmoothingEnabled = true;
  mCtx.imageSmoothingQuality = 'high';

  const frameCanvases = [];
  const frameUrls = [];

  for (let f = 0; f < 4; f++) {
    const sx = f * colW;
    const sw = f === 3 ? (w - sx) : colW;
    const fCv = cropTrimmedRegionToCanvas(cleanCanvas, sx, 0, sw, h, cellW, cellH, f !== 3);
    if (f === 3) {
      // 4번 환호·점프 포즈는 살짝 위로 띄워 역동적인 체공감 부여
      mCtx.drawImage(fCv, f * cellW, -16);
    } else {
      mCtx.drawImage(fCv, f * cellW, 0);
    }
    frameCanvases.push(fCv);
    frameUrls.push(fCv.toDataURL('image/png'));
  }

  const baseTex = new THREE.CanvasTexture(master);
  baseTex.colorSpace = THREE.SRGBColorSpace;
  baseTex.wrapS = THREE.ClampToEdgeWrapping;
  baseTex.wrapT = THREE.ClampToEdgeWrapping;
  baseTex.repeat.set(0.25, 1.0);
  baseTex.offset.set(0, 0);
  baseTex.needsUpdate = true;

  return {
    canvas: master,
    baseTex,
    frameCanvases,
    frameUrls
  };
}

function split2x2Sheet(srcImgOrCanvas) {
  const fullW = Math.max(4, srcImgOrCanvas.naturalWidth || srcImgOrCanvas.width || 512);
  const fullH = Math.max(4, srcImgOrCanvas.naturalHeight || srcImgOrCanvas.height || 512);
  const hw = Math.floor(fullW * 0.5);
  const hh = Math.floor(fullH * 0.5);
  // 중앙 분할 격자선 및 외곽 테두리 잔상을 100% 차단하기 위해 각 사분면 안쪽으로 12px 인셋 크롭!
  const insetX = Math.min(18, Math.max(6, Math.round(fullW * 0.016)));
  const insetY = Math.min(18, Math.max(6, Math.round(fullH * 0.016)));
  const quads = [
    [insetX, insetY, Math.max(8, hw - insetX * 2), Math.max(8, hh - insetY * 2)],
    [hw + insetX, insetY, Math.max(8, fullW - hw - insetX * 2), Math.max(8, hh - insetY * 2)],
    [insetX, hh + insetY, Math.max(8, hw - insetX * 2), Math.max(8, fullH - hh - insetY * 2)],
    [hw + insetX, hh + insetY, Math.max(8, fullW - hw - insetX * 2), Math.max(8, fullH - hh - insetY * 2)]
  ];
  const urls = [];
  const textures = [];
  const mats = [];
  const maxAniso = renderer?.capabilities?.getMaxAnisotropy ? renderer.capabilities.getMaxAnisotropy() : 8;

  for (const [sx, sy, sw, sh] of quads) {
    const rawQuad = document.createElement('canvas');
    rawQuad.width = sw;
    rawQuad.height = sh;
    const qCtx = rawQuad.getContext('2d', { willReadFrequently: true });
    qCtx.drawImage(srcImgOrCanvas, sx, sy, sw, sh, 0, 0, sw, sh);
    const cleanedQuad = removeWhiteBackground(rawQuad, 'vfx', 240);
    const subCv = cropTrimmedRegionToCanvas(cleanedQuad, 0, 0, sw, sh, 384, 384, false);
    urls.push(subCv.toDataURL('image/png'));
    const tex = new THREE.CanvasTexture(subCv);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = maxAniso;
    tex.needsUpdate = true;
    textures.push(tex);
    mats.push(new THREE.MeshBasicMaterial({
      map: tex,
      transparent: true,
      alphaTest: 0.06,
      side: THREE.DoubleSide
    }));
  }
  return { urls, textures, mats };
}

function loadRawImagePromise(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = (err) => reject(err);
    img.src = src;
  });
}

