  heartEyesGroup.visible = false;
  headGroup.add(heartEyesGroup);

  // 5) 360도 후면 하이브리드 꼬리 & 날개 & 황금 소나무 분재 등껍질(char_29_bonsai_tortoise)!
  const tailGroup = new THREE.Group();
  tailGroup.position.set(0, 0.42, -0.32);
